import { totalRevenueForMonth } from '../src/projections/billing.ts';

const MONTHS = ['2026-05', '2026-06', '2026-07'];
const events = loadEvents();

console.log(MONTHS.map((m) => `${m}=${totalRevenueForMonth(events, m)}`).join(' '));

